export const MigrationTool = () => {
    const [status, setStatus] = useState<string>('Ready');
    const [loading, setLoading] = useState(false);

    const runMigration = async () => {
        if (!confirm('This will overwrite matching IDs in Firestore. Continue?')) return;
        setLoading(true);
        setStatus('Migrating profiles...');

        try {
            // 1. Migrate Profiles
            for (const profile of MIGRATION_DATA.profiles) {
                await setDoc(doc(db, 'profiles', profile.id), profile);
            }

            setStatus('Migrating materials...');
            // 2. Migrate Learning Materials
            for (const material of MIGRATION_DATA.materials) {
                await setDoc(doc(db, 'materials', material.id), material);
            }

            setStatus('Migrating blog posts...');
            // 3. Migrate Blog Posts
            for (const post of MIGRATION_DATA.blog_posts) {
                await setDoc(doc(db, 'blog_posts', post.id), post);
            }

            setStatus('Migration Successful!');
        } catch (err: any) {
            console.error(err);
            setStatus('Error: ' + err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="bg-white p-10 rounded-3xl border border-slate-200">
            <h2 className="text-2xl font-black text-slate-900 uppercase mb-4">Supabase to Firestore Migration</h2>
            <p className="text-slate-500 mb-8">
                This tool imports users, materials, and blog posts from the Supabase export.
                <strong> nunommonteiro1972@gmail.com</strong> will be set as <strong>super_admin</strong>.
            </p>

            <div className="flex items-center gap-6">
                <button
                    onClick={runMigration}
                    disabled={loading}
                    className={`px-8 py-4 rounded-2xl bg-primary text-white font-black uppercase tracking-widest text-xs hover:shadow-xl transition-all ${loading ? 'opacity-50' : ''}`}
                >
                    {loading ? 'Running...' : 'Start Migration'}
                </button>
                <span className="text-sm font-bold text-slate-400 uppercase tracking-widest">{status}</span>
            </div>
        </div>
    );
};
